<?php $active_menu='payroll';include 'header.php';require_once __DIR__.'/../foundation.php';oecrm_require_permission($conn,'payroll','view');$companyId=oecrm_current_company_id($conn);$year=(int)($_GET['year']??date('Y'));$month=(int)($_GET['month']??date('n',strtotime('first day of last month')));$flash=$_SESSION['payroll_flash']??'';$error=$_SESSION['payroll_error']??'';unset($_SESSION['payroll_flash'],$_SESSION['payroll_error']);$stmt=mysqli_prepare($conn,'SELECT * FROM payroll_runs WHERE company_id=? AND period_year=? AND period_month=?');mysqli_stmt_bind_param($stmt,'iii',$companyId,$year,$month);mysqli_stmt_execute($stmt);$run=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);$items=null;if($run)$items=mysqli_query($conn,'SELECT p.*,e.employeeCode,e.name,e.designation FROM payroll_items p JOIN employeestbl e ON e.id=p.employee_id WHERE p.payroll_run_id='.(int)$run['id'].' ORDER BY e.name');$lock=mysqli_fetch_assoc(mysqli_query($conn,'SELECT * FROM attendance_period_locks WHERE company_id='.(int)$companyId.' AND period_year='.(int)$year.' AND period_month='.(int)$month));?>
<div id="page-wrapper" class="compact-admin-page payroll-page"><?php if($flash):?><div class="alert alert-success"><?php echo oecrm_h($flash);?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?php echo oecrm_h($error);?></div><?php endif;?><div class="payroll-toolbar"><form method="get"><select class="form-control" name="month"><?php for($m=1;$m<=12;$m++):?><option value="<?php echo $m;?>" <?php echo $month===$m?'selected':'';?>><?php echo date('F',mktime(0,0,0,$m,1));?></option><?php endfor;?></select><select class="form-control" name="year"><?php for($y=date('Y')-3;$y<=date('Y')+1;$y++):?><option <?php echo $year===$y?'selected':'';?>><?php echo $y;?></option><?php endfor;?></select><button class="btn btn-primary"><i class="fa fa-filter"></i> View</button></form><div class="payroll-actions"><span class="payroll-lock-state <?php echo !empty($lock['is_locked'])?'locked':'open';?>"><i class="fa <?php echo !empty($lock['is_locked'])?'fa-lock':'fa-unlock';?>"></i> Attendance <?php echo !empty($lock['is_locked'])?'Locked':'Open';?></span><form method="post" action="payrollAction.php"><?php echo oecrm_csrf_field();?><input type="hidden" name="year" value="<?php echo $year;?>"><input type="hidden" name="month" value="<?php echo $month;?>"><button name="action" value="<?php echo $run?'recalculate':'generate';?>" class="btn btn-primary"><i class="fa fa-calculator"></i> <?php echo $run?'Recalculate':'Generate Payroll';?></button></form></div></div>
<?php if($run):?><div class="payroll-summary"><div><small>Employees</small><strong><?php echo (int)$run['employee_count'];?></strong></div><div><small>Gross Payroll</small><strong>Rs. <?php echo number_format($run['gross_total'],2);?></strong></div><div><small>Deductions</small><strong>Rs. <?php echo number_format($run['deduction_total'],2);?></strong></div><div><small>Retention</small><strong>Rs. <?php echo number_format($run['retention_total'],2);?></strong></div><div class="net"><small>Net Payroll</small><strong>Rs. <?php echo number_format($run['net_total'],2);?></strong></div><div><small>Status</small><span class="payroll-status <?php echo $run['status'];?>"><?php echo oecrm_h(ucwords(str_replace('_',' ',$run['status'])));?></span></div></div>
<div class="panel panel-default"><div class="panel-heading payroll-heading"><span>Payroll Register - <?php echo date('F Y',strtotime(sprintf('%04d-%02d-01',$year,$month)));?></span><div class="payroll-heading-actions"><?php if(in_array($run['status'],['approved','locked'],true)):?><a class="btn btn-default btn-sm" target="_blank" href="bulkSalarySlips.php?run_id=<?php echo (int)$run['id'];?>"><i class="fa fa-file-pdf-o"></i> Bulk Slips</a><a class="btn btn-default btn-sm" href="payrollBankExport.php?run_id=<?php echo (int)$run['id'];?>"><i class="fa fa-bank"></i> Bank CSV</a><?php endif;?><a class="btn btn-default btn-sm" href="payrollSummaryExport.php?run_id=<?php echo (int)$run['id'];?>"><i class="fa fa-download"></i> Summary CSV</a><?php if($run['status']==='generated'):?><form method="post" action="payrollAction.php"><?php echo oecrm_csrf_field();?><input type="hidden" name="year" value="<?php echo $year;?>"><input type="hidden" name="month" value="<?php echo $month;?>"><button name="action" value="submit" class="btn btn-info btn-sm">Submit for Approval</button></form><?php elseif($run['status']==='pending_approval'):?><form method="post" action="payrollAction.php"><?php echo oecrm_csrf_field();?><input type="hidden" name="year" value="<?php echo $year;?>"><input type="hidden" name="month" value="<?php echo $month;?>"><button name="action" value="approve" class="btn btn-success btn-sm">Approve Payroll</button></form><?php elseif($run['status']==='approved'):?><form method="post" action="payrollAction.php"><?php echo oecrm_csrf_field();?><input type="hidden" name="year" value="<?php echo $year;?>"><input type="hidden" name="month" value="<?php echo $month;?>"><button name="action" value="lock" class="btn btn-danger btn-sm">Lock Payroll</button></form><?php endif;?></div></div><div class="panel-body table-responsive"><table class="table foundation-table payroll-table"><thead><tr><th>Employee</th><th>Slip</th><th>Present</th><th>Paid Leave</th><th>Unpaid</th><th>Gross</th><th>Attendance Ded.</th><th>Leave Ded.</th><th>PT</th><th>Retention</th><th>Total Ded.</th><th>Net Salary</th></tr></thead><tbody><?php while($p=mysqli_fetch_assoc($items)):?><tr><td><strong><?php echo oecrm_h($p['name']);?></strong><small><?php echo oecrm_h($p['employeeCode'].' - '.$p['designation']);?></small></td><td><a class="payroll-slip-link" href="salarySlip.php?id=<?php echo (int)$p['id']; ?>" target="_blank" title="Salary Slip"><i class="fa fa-file-pdf-o"></i></a></td><td><?php echo number_format($p['present_days'],1);?></td><td><?php echo number_format($p['paid_leave_days'],1);?></td><td><?php echo number_format($p['unpaid_leave_days'],1);?></td><td>Rs. <?php echo number_format($p['gross_salary'],2);?></td><td>Rs. <?php echo number_format($p['attendance_deduction'],2);?></td><td>Rs. <?php echo number_format($p['leave_deduction'],2);?></td><td>Rs. <?php echo number_format($p['professional_tax'],2);?></td><td>Rs. <?php echo number_format($p['retention_amount'],2);?></td><td>Rs. <?php echo number_format($p['total_deduction'],2);?></td><td class="net-cell">Rs. <?php echo number_format($p['net_salary'],2);?></td></tr><?php endwhile;?></tbody></table></div></div><?php else:?><div class="panel panel-default payroll-empty"><div class="panel-body"><i class="fa fa-calculator"></i><h3>No payroll generated</h3><p>Generate payroll for <?php echo date('F Y',strtotime(sprintf('%04d-%02d-01',$year,$month)));?> to calculate employee salaries.</p></div></div><?php endif;?></div><?php include 'footer.php';?>

